export const SILENT_MP3 = 'data:audio/mp3;base64,';

export const speak = (text, rate = 1.0, log = console.log) => {
    if (!text) return;
    log(`Speaking: ${text.substring(0, 10)}... @ ${rate}`);

    try {
        if ('speechSynthesis' in window && window.speechSynthesis) {
            // Cancel persistent synthesis (or overlap?)
            window.speechSynthesis.cancel();

            // Use Chinese voice if text has Chinese, else English
            // Heuristic: Check for Chinese characters
            const isChinese = /[\u4E00-\u9FFF]/.test(text);

            if ('SpeechSynthesisUtterance' in window && window.SpeechSynthesisUtterance) {
                const utterance = new SpeechSynthesisUtterance(text);
                utterance.rate = rate; // 1.0 = normal, 0.25 = slow

                // Find voice
                const voices = window.speechSynthesis.getVoices();
                if (voices && voices.length > 0) {
                    if (isChinese) {
                        const zhVoice = voices.find(v => v && v.lang && v.lang.includes('zh')); // zh-CN, zh-HK, zh-TW
                        if (zhVoice) utterance.voice = zhVoice;
                    } else {
                        // Prefer English
                        const enVoice = voices.find(v => v && v.lang && v.lang.startsWith('en'));
                        if (enVoice) utterance.voice = enVoice;
                    }
                }

                window.speechSynthesis.speak(utterance);
            } else {
                log("SpeechSynthesisUtterance not supported in this browser");
            }
        } else {
            log("SpeechSynthesis not supported in this browser");
        }
    } catch (e) {
        log(`Speech Synthesis speak error: ${e.message}`);
        console.error("Speech Synthesis error", e);
    }
};

export const initMediaSession = ({ onNext, onPrev, onPlay, onPause, title, artist, album, log = console.log }) => {
    try {
        if ('mediaSession' in navigator) {
            log("MediaSession available");
            
            // Safeguard MediaMetadata
            if (window.MediaMetadata) {
                try {
                    navigator.mediaSession.metadata = new MediaMetadata({
                        title: title || 'Hands Free Practice',
                        artist: artist || 'Flash Cards',
                        album: album || 'Bubble Game'
                    });
                } catch (e) {
                    log(`Failed to create MediaMetadata: ${e.message}`);
                }
            } else {
                log("MediaMetadata constructor not available");
            }

            if (onNext) {
                try {
                    navigator.mediaSession.setActionHandler('nexttrack', () => { log("Media: Next"); onNext(); });
                } catch (e) { log(`MediaSession setActionHandler nexttrack error: ${e.message}`); }
            }
            if (onPrev) {
                try {
                    navigator.mediaSession.setActionHandler('previoustrack', () => { log("Media: Prev"); onPrev(); });
                } catch (e) { log(`MediaSession setActionHandler previoustrack error: ${e.message}`); }
            }
            if (onPlay) {
                try {
                    navigator.mediaSession.setActionHandler('play', () => { log("Media: Play"); onPlay(); });
                } catch (e) { log(`MediaSession setActionHandler play error: ${e.message}`); }
            }
            if (onPause) {
                try {
                    navigator.mediaSession.setActionHandler('pause', () => { log("Media: Pause"); onPause(); });
                } catch (e) { log(`MediaSession setActionHandler pause error: ${e.message}`); }
            }

            return () => {
                try {
                    navigator.mediaSession.setActionHandler('nexttrack', null);
                } catch (e) {}
                try {
                    navigator.mediaSession.setActionHandler('previoustrack', null);
                } catch (e) {}
                try {
                    navigator.mediaSession.setActionHandler('play', null);
                } catch (e) {}
                try {
                    navigator.mediaSession.setActionHandler('pause', null);
                } catch (e) {}
            };
        } else {
            log("MediaSession NOT available");
            return () => { };
        }
    } catch (e) {
        log(`Error inside initMediaSession: ${e.message}`);
        console.error("initMediaSession error", e);
        return () => {};
    }
};

export const updateMediaMetadata = (title, artist) => {
    try {
        if ('mediaSession' in navigator && navigator.mediaSession.metadata) {
            if (title) navigator.mediaSession.metadata.title = title;
            if (artist) navigator.mediaSession.metadata.artist = artist;
        }
    } catch (e) {
        console.error("updateMediaMetadata error", e);
    }
};

export const warmupAudio = (audioElement, log = console.log) => {
    if (!audioElement) return;

    // 1. Resume Audio Context / Play Silent Audio
    try {
        audioElement.volume = 0.1;
        audioElement.play()
            .then(() => log("Audio Context resumed"))
            .catch(e => log(`Audio Play/Context Error: ${e.message}`));
    } catch (e) {
        log(`Audio warmup exception: ${e.message}`);
    }

    // 2. Warm up Speech Synthesis
    try {
        if ('speechSynthesis' in window && window.speechSynthesis) {
            window.speechSynthesis.cancel();
            if ('SpeechSynthesisUtterance' in window && window.SpeechSynthesisUtterance) {
                const utterance = new SpeechSynthesisUtterance('');
                window.speechSynthesis.speak(utterance);
                log("Speech Synthesis warmed up");
            }
        }
    } catch (e) {
        log(`Speech Synthesis warmup error: ${e.message}`);
    }
};

export const setupSpeechRecognition = ({ onResult, onError, log = console.log }) => {
    try {
        if (!('webkitSpeechRecognition' in window || 'SpeechRecognition' in window)) {
            log("Speech Recognition NOT supported");
            return null;
        }

        const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
        const recognition = new SpeechRecognition();
        recognition.continuous = true;
        recognition.interimResults = true;
        recognition.lang = 'en-US';

        recognition.onresult = (event) => {
            try {
                let interimTranscript = '';
                let finalTranscript = '';

                for (let i = event.resultIndex; i < event.results.length; ++i) {
                    if (event.results[i].isFinal) {
                        finalTranscript += event.results[i][0].transcript;
                    } else {
                        interimTranscript += event.results[i][0].transcript;
                    }
                }
                onResult(finalTranscript, interimTranscript);
            } catch (e) {
                log(`Error in speech recognition onresult: ${e.message}`);
            }
        };

        recognition.onerror = (event) => {
            log(`Speech Error event: ${event.error}`);
            if (onError) onError(event.error);
        };

        return recognition;
    } catch (e) {
        log(`Error setting up Speech Recognition: ${e.message}`);
        console.error("setupSpeechRecognition error", e);
        return null;
    }
};

